using LiveryStudio.Core;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Media;
using System.Text.Json;
using Windows.Storage.Pickers;

namespace LiveryStudio;

public sealed partial class CarBuilderWindow : Window
{
    private readonly VehicleAssemblyService service=new();
    private readonly WorkshopService paintService;
    private VehicleAssemblyProject project=new(){Name="Widebody Flight"};
    private VehicleImportManager imports;
    private ManagedVehicle? installed;
    private CancellationTokenSource? cancellation;
    private int step;
    private bool loading=true,busy,closing,draining,pendingClose;
    private readonly List<string> log=[];
    public CarBuilderWindow(string gameData,string tools,VehicleAssemblyProject? startingProject=null,bool advanced=false)
    {
        InitializeComponent();Title="Car Builder · Livery Studio";AppWindow.SetIcon(Path.Combine(AppContext.BaseDirectory,"Assets","LiveryStudio.ico"));
        paintService=new WorkshopService(tools,WorkshopService.DefaultWorkspace);imports=new(service);
        Painter.HostWindow=this;Painter.SetPreviewOnly(true);Painter.MapsSaved+=(a,s,e)=>{project.Paint.Albedo=a;project.Paint.Structure=s;project.Paint.EditorFile=e;};Painter.FinishEdited+=p=>project.Paint=p;Painter.Failure+=s=>log.Add(s);
        void Log(string line){lock(log)log.Add(line);}
        service.Log+=Log;paintService.Log+=Log;service.Progress+=(v,s)=>DispatcherQueue.TryEnqueue(()=>Status.Text=s);paintService.Progress+=(v,s)=>DispatcherQueue.TryEnqueue(()=>Status.Text=s);
        GameData.Text=GameInstallationDiscovery.Inspect(gameData)?.Data??GameInstallationDiscovery.FindSteam().FirstOrDefault()?.Root??gameData;Donor.ItemsSource=service.Donors();Donor.SelectedIndex=0;project.DonorIndex=(Donor.SelectedItem as VehicleDonor)?.Index??0;
        var area=Microsoft.UI.Windowing.DisplayArea.GetFromWindowId(AppWindow.Id,Microsoft.UI.Windowing.DisplayAreaFallback.Primary).WorkArea;
        AppWindow.Resize(new(Math.Min(1380,area.Width-32),Math.Min(940,area.Height-32)));AppWindow.Move(new(area.X+24,area.Y+24));
        AppWindow.Closing+=async(_,e)=>{if(closing)return;e.Cancel=true;if(draining)return;if(busy){pendingClose=true;cancellation?.Cancel();Status.Text="Finishing the current operation before closing…";return;}draining=true;Commands(false);try{await Painter.FlushAsync();await AutoSave();closing=true;Close();}catch(Exception x){draining=false;Commands(true);Failure(x);}};Closed+=(_,_)=>Painter.Dispose();
        Root.Loaded+=async(_,_)=>{var scale=Root.XamlRoot?.RasterizationScale??1;AppWindow.Resize(new(Math.Min((int)(1100*scale),area.Width),Math.Min((int)(820*scale),area.Height)));if(startingProject is not null){await Operate(async t=>{project=startingProject;ApplyRecipe();await LoadPreview();ShowStep(2);await AutoSave();});return;}var last=Path.Combine(service.Workspace,"Last car.flcar");if(File.Exists(last))await Operate(t=>OpenPath(last,t));};
        loading=false;SetCarMode(advanced);ShowStep(0);RefreshInstalled();
    }
    private void SetCarMode(bool advanced){Painter.SetAdvancedMode(advanced);CarModeButton.Content=advanced?"Simple mode":"Advanced mode";}
    private void ToggleCarMode(object sender,RoutedEventArgs e)=>SetCarMode(!Painter.AdvancedMode);
    private async Task AutoSave(){if(project.Prepared){var path=Path.Combine(service.Workspace,"working-cars",project.Id+".flcar");await Task.Run(()=>{VehicleProjectBundle.Save(project,path);AtomicFiles.Write(Path.Combine(service.Workspace,"Last car.flcar"),File.ReadAllBytes(path));});}}
    private void ReadRecipe(){project.Name=CarName.Text.Trim();if(project.Paint.IndependentPaintSides)return;project.DonorIndex=(Donor.SelectedItem as VehicleDonor)?.Index??0;project.KeepInterior=Interior.IsChecked==true;project.Fit=new(){AutoFit=AutoFit.IsChecked==true,Width=Width.Value/100,Length=Length.Value/100,Height=Height.Value/100,Yaw=Yaw.Value,Side=Side.Value,Forward=Forward.Value,Up=Up.Value};}
    private void ApplyRecipe(){loading=true;try{CarName.Text=project.Name;Donor.SelectedItem=((IEnumerable<VehicleDonor>)Donor.ItemsSource).FirstOrDefault(d=>d.Index==project.DonorIndex);Interior.IsChecked=project.KeepInterior;AutoFit.IsChecked=project.Fit.AutoFit;Width.Value=project.Fit.Width*100;Length.Value=project.Fit.Length*100;Height.Value=project.Fit.Height*100;Yaw.Value=project.Fit.Yaw;Side.Value=project.Fit.Side;Forward.Value=project.Fit.Forward;Up.Value=project.Fit.Up;SourceLabel.Text=Path.GetFileName(project.ExteriorFile);}finally{loading=false;}}
    private void NameChanged(object sender,TextChangedEventArgs e){if(loading||busy)return;ReadRecipe();}
    private void RecipeChanged(object sender,RoutedEventArgs e){Changed();}
    private void FitChanged(NumberBox sender,NumberBoxValueChangedEventArgs e){Changed();}
    private void Changed(){if(loading||busy)return;ReadRecipe();Status.Text="Recipe changed · update the preview before painting or building.";BuildButton.IsEnabled=false;}
    private void GameChanged(object sender,TextChangedEventArgs e){if(!loading)RefreshInstalled();}
    private void ShowStep(int value){var independent=project.Paint.IndependentPaintSides;ExteriorStep.Visibility=FitStep.Visibility=independent?Visibility.Collapsed:Visibility.Visible;PaintStep.Content=independent?"Paint":"3  Paint";DriveStep.Content=independent?"Use in game":"4  Drive";Subtitle.Text=independent?"Independent paint on each side - original car and surface details retained":"A new exterior. A proven foundation.";step=Math.Clamp(value,0,3);ExteriorPanel.Visibility=step==0?Visibility.Visible:Visibility.Collapsed;FitPanel.Visibility=step==1?Visibility.Visible:Visibility.Collapsed;DrivePanel.Visibility=step==3?Visibility.Visible:Visibility.Collapsed;Painter.SetPreviewOnly(step!=2);NextButton.Content=independent?(step==2?"Use in game":"Back to paint"):new[]{"Next: fit","Next: paint","Next: drive","Back to exterior"}[step];foreach(var b in new[]{ExteriorStep,FitStep,PaintStep,DriveStep})b.Background=(string)b.Tag==step.ToString()?(Brush)Application.Current.Resources["StudioNavSelectedBrush"]:new SolidColorBrush(Microsoft.UI.Colors.Transparent);Layout();}
    private async void ChooseStep(object sender,RoutedEventArgs e){if(busy||draining)return;var next=int.Parse((string)((Button)sender).Tag);if(next==2&&!project.Prepared){Status.Text="Import an exterior and update the preview before painting.";return;}try{await Painter.FlushAsync();ShowStep(next);}catch(Exception x){Failure(x);}}
    private async void Next(object sender,RoutedEventArgs e){if(busy||draining)return;var next=project.Paint.IndependentPaintSides?(step==2?3:2):(step+1)%4;if(next==2&&!project.Prepared){Status.Text="Update the preview before painting.";return;}try{await Painter.FlushAsync();ShowStep(next);}catch(Exception x){Failure(x);}}
    private void LayoutChanged(object sender,SizeChangedEventArgs e)=>Layout();
    private void Layout(){if(Work is null||SettingsCard is null)return;var compact=Root.ActualWidth<920;var paint=step==2;SettingsCard.Visibility=paint?Visibility.Collapsed:Visibility.Visible;SettingsColumn.Width=new(paint||compact?0:292);CompactSettingsRow.Height=new(compact&&!paint?Math.Min(200,Math.Max(130,Root.ActualHeight*.3)):0);Grid.SetColumn(SettingsCard,0);Grid.SetRow(SettingsCard,compact?1:0);Grid.SetColumnSpan(SettingsCard,compact?2:1);Grid.SetColumn(PreviewArea,compact||paint?0:1);Grid.SetColumnSpan(PreviewArea,compact||paint?2:1);Work.ColumnSpacing=compact||paint?0:16;Root.Padding=new(Root.ActualWidth<700?10:20,12,Root.ActualWidth<700?10:20,12);Subtitle.Visibility=Root.ActualWidth<760?Visibility.Collapsed:Visibility.Visible;}
    private void Commands(bool enabled){void Set(DependencyObject parent){if(parent is Control control)control.IsEnabled=enabled;for(var i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++)Set(VisualTreeHelper.GetChild(parent,i));}CarModeButton.IsEnabled=OpenCarButton.IsEnabled=SaveCarButton.IsEnabled=Painter.IsEnabled=enabled;Set(Steps);Set(SettingsCard);if(enabled)RefreshInstalled();}
    private async Task Operate(Func<CancellationToken,Task> action){if(busy||draining)return;busy=true;cancellation=new();Commands(false);Progress.Visibility=CancelButton.Visibility=Visibility.Visible;NextButton.Visibility=Visibility.Collapsed;Notice.IsOpen=false;try{await action(cancellation.Token);}catch(OperationCanceledException){Status.Text="Canceled · your previous car is preserved.";}catch(Exception x){Failure(x);}finally{busy=false;cancellation.Dispose();cancellation=null;Commands(true);Progress.Visibility=CancelButton.Visibility=Visibility.Collapsed;NextButton.Visibility=Visibility.Visible;RefreshInstalled();WriteLog();if(pendingClose){pendingClose=false;Close();}}}
    private void WriteLog(){try{Directory.CreateDirectory(service.Workspace);lock(log)File.WriteAllText(Path.Combine(service.Workspace,"car-builder.log"),string.Join(Environment.NewLine,log));}catch{}}
    private void Failure(Exception x){log.Add(x.ToString());Notice.Title="Car needs attention";Notice.Message=x.Message;Notice.Severity=InfoBarSeverity.Error;Notice.IsOpen=true;Status.Text="Your previous project and recovery files are preserved.";}
    private void Cancel(object sender,RoutedEventArgs e)=>cancellation?.Cancel();
    private async Task LoadPreview(){await Painter.LoadAsync(project.Paint,project.PreviewFile);Painter.Visibility=Visibility.Visible;EmptyPreview.Visibility=Visibility.Collapsed;Painter.SetPreviewOnly(step!=2);var report=JsonSerializer.Deserialize<VehicleSceneReport>(File.ReadAllText(project.ReportFile),Contract.Json)!;Status.Text=project.Paint.IndependentPaintSides?"Each side has its own paint. Save car keeps the model, artwork and full Undo history.":$"{report.ImportedTriangles:N0} new exterior triangles · {report.RetainedInteriorTriangles:N0} donor interior triangles · donor wheels retained";RefreshInstalled();}
    private async Task ImportPath(string path,CancellationToken token){ReadRecipe();await Painter.FlushAsync();await service.ImportAsync(project,path,token);ApplyRecipe();await LoadPreview();await AutoSave();}
    private async void ImportExterior(object sender,RoutedEventArgs e){if(busy||draining)return;try{if(await Pick([".fbx",".obj",".glb"]) is{} path)await Operate(t=>ImportPath(path,t));}catch(Exception x){Failure(x);}}
    private async void Example(object sender,RoutedEventArgs e){await Operate(async t=>{AutoFit.IsChecked=false;project.Fit.AutoFit=false;await ImportPath(Path.Combine(AppContext.BaseDirectory,"Examples","WidebodyExterior.obj"),t);});}
    private async void UpdatePreview(object sender,RoutedEventArgs e){await Operate(async t=>{ReadRecipe();await Painter.FlushAsync();await service.PrepareAsync(project,t);await LoadPreview();await AutoSave();});}
    private async Task<string?> Pick(string[] types){var picker=new FileOpenPicker();WinRT.Interop.InitializeWithWindow.Initialize(picker,WinRT.Interop.WindowNative.GetWindowHandle(this));foreach(var ext in types)picker.FileTypeFilter.Add(ext);return(await picker.PickSingleFileAsync())?.Path;}
    private async Task OpenPath(string file,CancellationToken token){var loaded=await Task.Run(()=>VehicleProjectBundle.Open(file,service.Workspace),token);service.Donor(loaded.DonorIndex);project=loaded;if(project.Paint.IndependentPaintSides)await service.PrepareAsync(project,token);ApplyRecipe();if(project.Prepared)await LoadPreview();else{Painter.Visibility=Visibility.Collapsed;EmptyPreview.Visibility=Visibility.Visible;}ShowStep(project.Paint.IndependentPaintSides?2:step);await AutoSave();}
    private async void OpenCar(object sender,RoutedEventArgs e){if(busy||draining)return;try{if(await Pick([".flcar"]) is{} file)await Operate(async t=>{await Painter.FlushAsync();await AutoSave();await OpenPath(file,t);});}catch(Exception x){Failure(x);}}
    private async void SaveCar(object sender,RoutedEventArgs e){if(busy||draining)return;try{ReadRecipe();await Painter.FlushAsync();var picker=new FileSavePicker{SuggestedFileName=project.Name};picker.FileTypeChoices.Add("Editable car project",[".flcar"]);WinRT.Interop.InitializeWithWindow.Initialize(picker,WinRT.Interop.WindowNative.GetWindowHandle(this));if(await picker.PickSaveFileAsync() is{} file)await Operate(async t=>{await Task.Run(()=>VehicleProjectBundle.Save(project,file.Path),t);Status.Text="Car saved with its exterior, donor recipe, artwork and edit history.";});}catch(Exception x){Failure(x);}}
    private async void PickGame(object sender,RoutedEventArgs e){try{var picker=new FolderPicker();picker.FileTypeFilter.Add("*");WinRT.Interop.InitializeWithWindow.Initialize(picker,WinRT.Interop.WindowNative.GetWindowHandle(this));if(await picker.PickSingleFolderAsync() is{} folder)GameData.Text=folder.Path;}catch(Exception x){Failure(x);}}
    private async void BuildInstall(object sender,RoutedEventArgs e){await Operate(async t=>{ReadRecipe();await Painter.FlushAsync();await AutoSave();var data=GameData.Text;if(GameInstallationDiscovery.Inspect(data) is {Kind:GameInstallationKind.Steam} steam){await BuildSteam(steam,t);return;}var built=await service.BuildAsync(project,paintService,data,t);t.ThrowIfCancellationRequested();installed=await Task.Run(()=>imports.Install(built,data));imports.Verify(installed,data);RefreshInstalled();Status.Text="Installed and verified · launch the non-VR game and select this WK_ livery.";});}
    private void Launch(object sender,RoutedEventArgs e){try{if(GameInstallationDiscovery.Inspect(GameData.Text) is {Kind:GameInstallationKind.Steam} steam){LaunchSteam(steam);return;}if(installed is{} current)imports.Verify(current,GameData.Text);using var process=DesktopGame.Launch(DesktopGame.Resolve(GameData.Text));Status.Text="Non-VR game launched · select the donor, then this car’s WK_ livery.";}catch(Exception x){Failure(x);}}
    private async void Restore(object sender,RoutedEventArgs e){if(installed is null&&steamInstalled is null)return;await Operate(async t=>{var data=GameData.Text;if(GameInstallationDiscovery.Inspect(data) is {Kind:GameInstallationKind.Steam} steam)await Task.Run(()=>SteamImports.Restore(steam.Root),t);else if(installed is {} current)await Task.Run(()=>imports.Restore(current,data),t);RefreshInstalled();Status.Text="Original car restored. Your car project is still saved.";});}
}
